package prairie.action

import data.prairie.lib.quality
import rego.v1

decision := tightened if {
	override := data.prairie_custom.action.override(base_decision, input)
	tightened := tighten(base_decision, override, input)
} else := base_decision

base_decision := download_decision(input) if {
	action(input) == "download"
} else := download_transcode_decision(input) if {
	action(input) == "download_transcode"
} else := playback_admission_decision(input) if {
	action(input) == "playback_admission"
} else := deny("unknown action", "unknown_action")

download_decision(i) := allow if {
	download_base_allowed(i)
	quality_allowed(i)
	rating_allowed(i)
} else := deny("downloads disabled", "downloads_disabled") if {
	not downloads_enabled(i)
} else := deny("download permission required", "download_permission_required") if {
	not download_allowed(i)
} else := deny("quality ceiling exceeded", "quality_ceiling_exceeded") if {
	not quality_allowed(i)
} else := deny("content rating exceeded", "content_rating_exceeded")

download_transcode_decision(i) := allow if {
	download_base_allowed(i)
	transcode_enabled(i)
	download_transcode_allowed(i)
	artifacts_available(i)
	quality_allowed(i)
	rating_allowed(i)
} else := deny("downloads disabled", "downloads_disabled") if {
	not downloads_enabled(i)
} else := deny("download permission required", "download_permission_required") if {
	not download_allowed(i)
} else := deny("transcode disabled", "transcode_disabled") if {
	not transcode_enabled(i)
} else := deny("download transcode permission required", "download_transcode_permission_required") if {
	not download_transcode_allowed(i)
} else := deny("download artifacts unavailable", "download_artifacts_unavailable") if {
	not artifacts_available(i)
} else := deny("quality ceiling exceeded", "quality_ceiling_exceeded") if {
	not quality_allowed(i)
} else := deny("content rating exceeded", "content_rating_exceeded")

playback_admission_decision(i) := allow if {
	transcode_allowed(i)
	stream_limit_allows(i)
	transcode_limit_allows(i)
} else := deny("audio transcoding disabled for user", "audio_transcoding_disabled") if {
	requested_action(i) == "audio_transcode"
	not transcode_allowed(i)
} else := deny("transcoding disabled for user", "transcoding_disabled") if {
	not transcode_allowed(i)
} else := deny("max streams exceeded", "max_streams_exceeded") if {
	not stream_limit_allows(i)
} else := deny("max transcodes exceeded", "max_transcodes_exceeded")

download_base_allowed(i) if {
	downloads_enabled(i)
	download_allowed(i)
}

quality_allowed(i) if {
	quality.allowed(file_quality(i), max_playback_quality(i))
}

# content_rating_within_ceiling is resolved in Go before evaluation, by both
# entry points that produce an action decision (PDP.CheckAction and
# policy.Simulate), because the maturity ladder lives there: ranking "15",
# "FSK 16" or "DE:16" against a "PG-13" ceiling is not something this policy
# can do.
#
# No ceiling asserted means allowed. A ceiling WITH no derived result is not
# treated as "no ceiling": that combination can only mean an evaluator forgot
# to derive the flag, and defaulting it to true would let a parental control
# pass silently. It denies instead, so a future third caller fails loudly on
# its first over-ceiling request rather than quietly serving one.
rating_allowed(i) if {
	object.get(i, "max_content_rating", "") == ""
} else if {
	object.get(i, "content_rating_within_ceiling", false) == true
}

stream_limit_allows(i) if {
	max_streams(i) == 0
} else if {
	current_active_streams(i) < max_streams(i)
}

transcode_limit_allows(i) if {
	requested_action(i) != "transcode"
} else if {
	max_transcodes(i) == 0
} else if {
	current_active_transcodes(i) < max_transcodes(i)
}

action(i) := object.get(i, "action", "")

downloads_enabled(i) if {
	object.get(i, "downloads_enabled", false) == true
}

transcode_enabled(i) if {
	object.get(i, "transcode_enabled", false) == true
}

transcode_allowed(i) if {
	requested_action(i) != "transcode"
	requested_action(i) != "audio_transcode"
} else if {
	object.get(i, "transcode_allowed", true) == true
} else if {
	requested_action(i) == "audio_transcode"
	object.get(i, "audio_transcode_allowed", true) == true
}

download_allowed(i) if {
	object.get(i, "download_allowed", false) == true
}

download_transcode_allowed(i) if {
	object.get(i, "download_transcode_allowed", false) == true
}

artifacts_available(i) if {
	object.get(i, "artifacts_available", false) == true
}

file_quality(i) := object.get(i, "file_quality", "")

max_playback_quality(i) := object.get(i, "max_playback_quality", "")

current_active_streams(i) := object.get(i, "current_active_streams", 0)

current_active_transcodes(i) := object.get(i, "current_active_transcodes", 0)

max_streams(i) := object.get(i, "max_streams", 0)

max_transcodes(i) := object.get(i, "max_transcodes", 0)

requested_action(i) := object.get(i, "requested_action", "")

allow := {
	"allowed": true,
	"reason": "allowed",
	"reason_code": "",
	"quality_ceiling": "",
}

# reason is human-readable free text; reason_code is the machine contract Go
# consumers switch on (see policy.ReasonCode* constants).
deny(reason, code) := {
	"allowed": false,
	"reason": reason,
	"reason_code": code,
	"quality_ceiling": "",
}

tighten(base, override, i) := result if {
	allowed := tightened_allowed(base, override)
	reason := tightened_reason(base, override, allowed)
	reason_code := tightened_reason_code(base, override, allowed)
	quality_ceiling := tightened_quality_ceiling(override, i)
	result := {
		"allowed": allowed,
		"reason": reason,
		"reason_code": reason_code,
		"quality_ceiling": quality_ceiling,
	}
}

# Only a literal boolean true keeps the base grant; any other override value
# (including malformed non-boolean output) tightens to a deny.
override_grants(override) if {
	object.get(override, "allowed", true) == true
}

tightened_allowed(base, override) := true if {
	base.allowed
	override_grants(override)
} else := false

tightened_reason(base, override, allowed) := reason if {
	not allowed
	base.allowed
	not override_grants(override)
	reason := nonempty_string_or_default(object.get(override, "reason", ""), base.reason)
} else := base.reason

# Overrides only carry free-text reasons, so a custom deny always gets the
# fixed custom_denial code; a base deny keeps its vendor code.
tightened_reason_code(base, override, allowed) := "custom_denial" if {
	not allowed
	base.allowed
	not override_grants(override)
} else := object.get(base, "reason_code", "")

tightened_quality_ceiling(override, i) := ceiling if {
	override_ceiling := object.get(override, "quality_ceiling", "")
	override_ceiling != ""
	clamped := quality.min(override_ceiling, max_playback_quality(i))
	clamped != quality.normalize(max_playback_quality(i))
	ceiling := clamped
} else := ""

nonempty_string_or_default(value, fallback) := value if {
	is_string(value)
	value != ""
} else := fallback

package prairie_custom.action

import rego.v1

override(_, _) := result if {
	result := {}
	false
}

package prairie_custom.permission

import rego.v1

override(_, _) := result if {
	result := {}
	false
}

package prairie_custom.scope

import rego.v1

override(_, _) := result if {
	result := {}
	false
}

package prairie.lib.quality

import rego.v1

rank := {
	"": 0,
	"480P": 1,
	"720P": 2,
	"1080P": 3,
	"2160P": 4,
	"4320P": 5,
}

normalize(value) := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u == ""
	normalized := ""
} else := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u == "ANY"
	normalized := ""
} else := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u in {"STANDARD", "480P", "720P", "1080P"}
	normalized := "1080p"
} else := normalized if {
	u := upper(trim(sprintf("%v", [value]), " "))
	u in {"4K", "UHD", "2160P", "4320P"}
	normalized := "2160p"
} else := ""

compare(a, b) := -1 if {
	rank[upper(trim(normalize(a), " "))] < rank[upper(trim(normalize(b), " "))]
} else := 1 if {
	rank[upper(trim(normalize(a), " "))] > rank[upper(trim(normalize(b), " "))]
} else := 0

allowed(file_quality, ceiling) if {
	normalize(ceiling) == ""
} else if {
	file_rank := object.get(rank, raw(file_quality), 0)
	ceiling_rank := object.get(rank, upper(trim(normalize(ceiling), " ")), 0)
	file_rank <= ceiling_rank
}

raw(value) := upper(trim(sprintf("%v", [value]), " "))

min(a, b) := result if {
	normalized_a := normalize(a)
	trim(normalized_a, " ") == ""
	result := normalize(b)
} else := result if {
	normalized_b := normalize(b)
	trim(normalized_b, " ") == ""
	result := normalize(a)
} else := result if {
	compare(a, b) <= 0
	result := normalize(a)
} else := normalize(b)

package prairie.permission

import rego.v1

decision := tightened if {
	override := data.prairie_custom.permission.override(base_decision, input)
	tightened := tighten(base_decision, override)
} else := base_decision

base_decision := acting_admin_decision(input) if {
	input.permission == "acting_admin"
} else := marker_edit_decision(input) if {
	input.permission == "marker_edit"
} else := metadata_curation_decision(input) if {
	input.permission == "metadata_curation"
} else := deny("unknown permission", "unknown_permission")

acting_admin_decision(i) := allow if {
	acting_admin_allowed(i)
} else := deny("user disabled", "user_disabled") if {
	not user_enabled(i)
} else := deny("admin role required", "admin_role_required") if {
	not admin_role(i)
} else := deny("primary profile required", "primary_profile_required")

marker_edit_decision(i) := allow if {
	effective_permission_allowed(i, "marker_edit")
} else := deny("user disabled", "user_disabled") if {
	not user_enabled(i)
} else := deny("marker edit permission required", "marker_edit_permission_required")

metadata_curation_decision(i) := allow if {
	acting_admin_allowed(i)
} else := allow if {
	user_enabled(i)
	assigned_permission(i, "metadata_curation")
	target_libraries_allowed(i)
} else := deny("user disabled", "user_disabled") if {
	not user_enabled(i)
} else := deny("metadata curation permission required", "metadata_curation_permission_required") if {
	not assigned_permission(i, "metadata_curation")
} else := deny("item is outside user libraries", "item_outside_user_libraries")

effective_permission_allowed(i, permission) if {
	user_enabled(i)
	assignable_permission(permission)
	admin_role(i)
} else if {
	user_enabled(i)
	assigned_permission(i, permission)
}

acting_admin_allowed(i) if {
	user_enabled(i)
	admin_role(i)
	declared_profile_id(i) == ""
	not household_requires_profile(i)
} else if {
	user_enabled(i)
	admin_role(i)
	declared_profile_id(i) != ""
	acting_as_primary(i)
}

target_libraries_allowed(i) if {
	count(target_library_ids(i)) > 0
	not user_libraries_restricted(i)
} else if {
	count(target_library_ids(i)) > 0
	user_libraries_restricted(i)
	every id in target_library_ids(i) {
		has_value(user_library_ids(i), id)
	}
}

assignable_permission("marker_edit")
assignable_permission("metadata_curation")

assigned_permission(i, permission) if {
	some idx
	assigned_permissions(i)[idx] == permission
}

admin_role(i) if {
	role(i) == "admin"
}

user_enabled(i) if {
	object.get(i, "user_enabled", false) == true
}

acting_as_primary(i) if {
	object.get(i, "acting_as_primary", false) == true
}

# A household with a PIN-protected or access-limited profile withholds admin
# powers from a request that declares no profile; precomputed in Go.
household_requires_profile(i) if {
	object.get(i, "household_requires_profile", false) == true
}

user_libraries_restricted(i) if {
	object.get(i, "user_libraries_restricted", false) == true
}

role(i) := object.get(i, "role", "")

declared_profile_id(i) := object.get(i, "declared_profile_id", "")

assigned_permissions(i) := values if {
	values := object.get(i, "assigned_permissions", [])
	is_array(values)
} else := []

target_library_ids(i) := values if {
	values := object.get(i, "target_library_ids", [])
	is_array(values)
} else := []

user_library_ids(i) := values if {
	values := object.get(i, "user_library_ids", [])
	is_array(values)
} else := []

has_value(values, value) if {
	some i
	values[i] == value
}

allow := {
	"allowed": true,
	"reason": "allowed",
	"reason_code": "",
}

# reason is human-readable free text; reason_code is the machine contract Go
# consumers switch on (see policy.ReasonCode* constants).
deny(reason, code) := {
	"allowed": false,
	"reason": reason,
	"reason_code": code,
}

tighten(base, override) := result if {
	allowed := tightened_allowed(base, override)
	reason := tightened_reason(base, override, allowed)
	reason_code := tightened_reason_code(base, override, allowed)
	result := {
		"allowed": allowed,
		"reason": reason,
		"reason_code": reason_code,
	}
}

# Only a literal boolean true keeps the base grant; any other override value
# (including malformed non-boolean output) tightens to a deny.
override_grants(override) if {
	object.get(override, "allowed", true) == true
}

tightened_allowed(base, override) := true if {
	base.allowed
	override_grants(override)
} else := false

tightened_reason(base, override, allowed) := reason if {
	not allowed
	base.allowed
	not override_grants(override)
	reason := nonempty_string_or_default(object.get(override, "reason", ""), base.reason)
} else := base.reason

# Overrides only carry free-text reasons, so a custom deny always gets the
# fixed custom_denial code; a base deny keeps its vendor code.
tightened_reason_code(base, override, allowed) := "custom_denial" if {
	not allowed
	base.allowed
	not override_grants(override)
} else := object.get(base, "reason_code", "")

nonempty_string_or_default(value, fallback) := value if {
	is_string(value)
	value != ""
} else := fallback

package prairie.scope

import rego.v1
import data.prairie.lib.quality

decision := tightened if {
	override := data.prairie_custom.scope.override(base_decision, input)
	tightened := tighten(base_decision, override)
} else := base_decision

base_decision := decision if {
	libraries := library_decision(input)
	decision := {
		"schema_version": input.schema_version,
		"unrestricted": libraries.unrestricted,
		"allowed_library_ids": libraries.allowed_library_ids,
		"disabled_library_ids": libraries.disabled_library_ids,
		"hidden_library_ids": libraries.hidden_library_ids,
		"libraries_restricted": libraries.libraries_restricted,
		"max_content_rating": max_content_rating(input),
		"max_content_rating_override": "",
		"max_advisory_age": max_advisory_age(input),
		"max_playback_quality": max_playback_quality(input),
		"preferred_metadata_language": preferred_metadata_language(input),
		"policy_revision": input.access_policy_revision,
		"profile_verified": input.profile_verified,
	}
}

library_decision(i) := result if {
	effective := effective_libraries(i)
	effective.unrestricted
	result := {
		"unrestricted": true,
		"allowed_library_ids": [],
		"disabled_library_ids": disabled_ids(i),
		"hidden_library_ids": [],
		"libraries_restricted": false,
	}
} else := result if {
	effective := effective_libraries(i)
	not effective.unrestricted
	result := {
		"unrestricted": false,
		"allowed_library_ids": subtract(effective.allowed_library_ids, disabled_ids(i)),
		"disabled_library_ids": [],
		# The allowed libraries the profile hid itself. They are not access:
		# a library list that lets the profile show them again reports them.
		"hidden_library_ids": intersect(effective.allowed_library_ids, disabled_ids(i)),
		"libraries_restricted": true,
	}
}

effective_libraries(i) := result if {
	i.account_restricted
	i.profile_present
	i.profile_library_restricted
	result := {
		"unrestricted": false,
		"allowed_library_ids": intersect(i.account_library_ids, i.profile_allowed_library_ids),
	}
} else := result if {
	i.account_restricted
	not profile_limits_libraries(i)
	result := {
		"unrestricted": false,
		"allowed_library_ids": array_or_empty(i.account_library_ids),
	}
} else := result if {
	not i.account_restricted
	i.profile_present
	i.profile_library_restricted
	result := {
		"unrestricted": false,
		"allowed_library_ids": unique_sorted(i.profile_allowed_library_ids),
	}
} else := {
	"unrestricted": true,
	"allowed_library_ids": [],
}

profile_limits_libraries(i) if {
	i.profile_present
	i.profile_library_restricted
}

max_content_rating(i) := rating if {
	i.profile_present
	rating := i.profile_max_content_rating
} else := ""

# max_advisory_age is the profile's advisory-age limit; 0 means no limit.
max_advisory_age(i) := age if {
	i.profile_present
	age := object.get(i, "profile_max_advisory_age", 0)
	is_number(age)
	age > 0
} else := 0

max_playback_quality(i) := quality.min(i.account_max_playback_quality, profile_quality(i))

profile_quality(i) := quality if {
	i.profile_present
	quality := i.profile_max_playback_quality
} else := ""

preferred_metadata_language(i) := language if {
	i.profile_present
	language := i.profile_preferred_metadata_language
} else := ""

disabled_ids(i) := ids if {
	is_array(i.disabled_library_ids)
	ids := i.disabled_library_ids
} else := []

array_or_empty(xs) := xs if {
	is_array(xs)
} else := []

intersect(left, right) := unique_sorted([id |
	some i
	id := right[i]
	has_value(left, id)
])

unique_sorted(values) := sort({id |
	some i
	id := values[i]
})

subtract(values, excluded) := [id |
	some i
	id := values[i]
	not has_value(excluded, id)
]

has_value(values, value) if {
	some i
	values[i] == value
}

# tighten combines the base decision with a custom override. The advisory-age
# limit is reduced to the lower of the two (see stricter_advisory_age). Every
# other dimension is reduced here too except the content rating: comparing "PG" with "15" or "FSK 16"
# needs the maturity ladder, which lives in Go only (internal/access). The
# override's ceiling is reported alongside the base one and the caller resolves
# the stricter of the two with access.StricterCeiling, so an override that names
# a rating this policy cannot rank can only tighten, never widen.
tighten(base, override) := result if {
	unrestricted := merged_unrestricted(base, override)
	disabled := merged_disabled(base, override)
	allowed := merged_allowed(base, override, unrestricted, disabled)
	libraries_restricted := restricted(unrestricted)
	max_quality := quality.min(base["max_playback_quality"], object.get(override, "max_playback_quality", ""))
	profile_verified := merged_profile_verified(base, override)
	output_disabled := disabled_if_unrestricted(disabled, unrestricted)
	hidden := merged_hidden(base, override, unrestricted)
	result := {
		"schema_version": base["schema_version"],
		"unrestricted": unrestricted,
		"allowed_library_ids": allowed,
		"disabled_library_ids": output_disabled,
		"hidden_library_ids": hidden,
		"libraries_restricted": libraries_restricted,
		"max_content_rating": base["max_content_rating"],
		"max_content_rating_override": object.get(override, "max_content_rating", ""),
		"max_advisory_age": stricter_advisory_age(base["max_advisory_age"], override_advisory_age(override)),
		"max_playback_quality": max_quality,
		"preferred_metadata_language": base["preferred_metadata_language"],
		"policy_revision": base["policy_revision"],
		"profile_verified": profile_verified,
	}
}

# override_advisory_age reads the advisory-age limit an override asks for. An
# absent, null or zero value asks for none. A positive number is floored to a
# whole age. Anything else (a negative number, a string, a boolean) is an
# unusable limit and, like an unusable parental control anywhere else, fails
# closed to the strictest limit there is.
override_advisory_age(o) := 0 if {
	object.get(o, "max_advisory_age", null) == null
} else := 0 if {
	o.max_advisory_age == 0
} else := age if {
	is_number(o.max_advisory_age)
	o.max_advisory_age >= 1
	age := floor(o.max_advisory_age)
} else := 1

# stricter_advisory_age keeps the lower of two advisory-age limits, where 0
# means "no limit" and so always loses to a real one.
stricter_advisory_age(a, b) := b if {
	a == 0
} else := a if {
	b == 0
} else := min([a, b])

restricted(unrestricted) := false if {
	unrestricted
} else := true

merged_unrestricted(base, override) := true if {
	base.unrestricted
	object.get(override, "unrestricted", base.unrestricted)
} else := false

merged_profile_verified(base, override) := true if {
	base.profile_verified
	object.get(override, "profile_verified", true)
} else := false

merged_disabled(base, override) := unique_sorted(array.concat(
	object.get(base, "disabled_library_ids", []),
	object.get(override, "disabled_library_ids", []),
))

merged_allowed(base, override, unrestricted, disabled) := [] if {
	unrestricted
} else := allowed if {
	not unrestricted
	base.unrestricted
	not object.get(override, "unrestricted", base.unrestricted)
	allowed := subtract(object.get(override, "allowed_library_ids", []), disabled)
} else := allowed if {
	not unrestricted
	not base.unrestricted
	object.get(override, "unrestricted", base.unrestricted)
	allowed := subtract(base.allowed_library_ids, disabled)
} else := allowed if {
	not unrestricted
	not base.unrestricted
	not object.get(override, "unrestricted", base.unrestricted)
	allowed := subtract(intersect(base.allowed_library_ids, object.get(override, "allowed_library_ids", [])), disabled)
}

# merged_hidden keeps the profile's hidden libraries that the override would
# still allow had the profile not hidden them. A restricted base carries them
# in hidden_library_ids and an unrestricted one in disabled_library_ids; the
# override's allowlist and disabled list narrow them as they narrow allowed.
merged_hidden(base, override, unrestricted) := [] if {
	unrestricted
} else := hidden if {
	hidden := subtract(hidden_candidates(base, override), object.get(override, "disabled_library_ids", []))
}

hidden_candidates(base, override) := ids if {
	not object.get(override, "unrestricted", base.unrestricted)
	ids := intersect(own_hidden(base), object.get(override, "allowed_library_ids", []))
} else := unique_sorted(own_hidden(base))

own_hidden(base) := array.concat(object.get(base, "hidden_library_ids", []), base.disabled_library_ids)

disabled_if_unrestricted(disabled, unrestricted) := disabled if {
	unrestricted
} else := []
